async function main(): Promise<void> {
  const events: string[] = [];
  const thenable: any = {
    get then() {
      events.push("get");
      return function (resolve: any): void {
        events.push("call");
        resolve(9);
      };
    },
  };
  events.push("before");
  const promise = Promise.resolve(thenable);
  events.push("after");
  console.log(await promise, events.join(","));
}
